import math

docs = {
    "warranty": [0.9, 0.1, 0.1],
    "payment": [0.1, 0.9, 0.2],
    "delivery": [0.4, 0.3, 0.8],
}
query = [0.8, 0.2, 0.2]

def cosine(a, b):
    dot = sum(x * y for x, y in zip(a, b))
    na = math.sqrt(sum(x * x for x in a))
    nb = math.sqrt(sum(y * y for y in b))
    return dot / (na * nb)

scores = {name: cosine(vec, query) for name, vec in docs.items()}
for name, s in scores.items():
    print(name, round(s, 2))
print("Best:", max(scores, key=scores.get))

