practice.solution:
STOP = {"kitni", "hai", "kab", "tak", "is", "of", "from"}
chunks = [
    "Warranty is 12 months from dispatch.",
    "Payment within 30 days of invoice.",
    "Delivery in 5 days.",
]

def words(t):
    t = t.lower().replace(".", "").replace("?", "")
    return set(t.split()) - STOP

def answer(q):
    qw = words(q)
    best = max(chunks, key=lambda c: len(qw & words(c)))
    if len(qw & words(best)) == 0:
        return "Nahi mila"
    return best

for q in ["warranty kitni hai?", "payment kab tak?", "cricket score?"]:
    print(q, "->", answer(q))
